import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Gergo matematico","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/h_algebra-astratta/hd/gergo.md","filePath":"lezioni/h_algebra-astratta/hd/gergo.md"}`),a={name:`lezioni/h_algebra-astratta/hd/gergo.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="gergo-matematico" tabindex="-1">Gergo matematico <a class="header-anchor" href="#gergo-matematico" aria-label="Permalink to “Gergo matematico”">​</a></h1><p>Sembra impossibile, ma, per quanto la matematica sia una scienza esatta, ogni docente ha una preferenza per certi termini piuttosto che per altri ed esistono termini diversi per indicare la stessa cosa: guarda ad esempio le definizioni di <a href="./../../j/jd/jd0.html">&quot;applicazione&quot;</a>.</p><blockquote><p>Ad esempio io preferisco usare l&#39;espressione &quot;resto infinitesimo di ordine superiore&quot; ma spesso ho sentito l&#39;espressione &quot;o piccolo&quot; che significa la stessa cosa. Altro esempio: negli integrali definiti ho inserito gli integrali generalizzati: da qualcuno ho sentito chiamarli &quot;integrali impropri&quot; oppure &quot;integrali sotto il segno di limite&quot;. Ancora nelle relazioni si dice iniezione oppure corrispondenza iniettiva od anche corrispondenza <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">1-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> per indicare la stessa relazione.</p></blockquote><p>Questo dipende sia da quale Università uno ha frequentato che dall&#39;abitudine per chi ripete sempre gli stessi concetti, di usare certe parole invece di altre: niente di grave, la matematica è la stessa, però se devi sostenere un esame cerca sempre di usare sia le espressioni che i modi di pensiero che utilizza l&#39;esaminatore: superare l&#39;esame ti risulterà più semplice.</p><blockquote><p><strong>Ricordati che</strong>, per te, la prima cosa è superare l&#39;esame: il resto, capire i concetti, saperli applicare e ragionarci sopra, vedrai che verrà di conseguenza.</p></blockquote>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};